// ============================================================================
// SGMII_apb: APB4 register wrapper around SGMII_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/SGMII.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/SGMII.md
// ============================================================================
module SGMII_apb #(
  parameter int LT_X = 1250000,
  parameter int LT_SG = 200000
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic [7:0] gtxd,
  input logic gtx_en,
  input logic gtx_er,
  output logic [7:0] grxd,
  output logic grx_dv,
  output logic grx_er,
  output logic [9:0] tx_code,
  input logic [9:0] rx_code
);
  localparam logic [31:0] ID_VALUE = 32'h53470100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [8:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd9) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_mode_sgmii;
  logic          c_an_en;
  logic          c_an_restart;
  logic [15:0]   c_adv;
  logic          c_sync_ok;
  logic          c_an_done;
  logic          c_link_up;
  logic [15:0]   c_lp_ability;
  logic [1:0]    c_speed;
  logic          c_full_duplex;
  logic          c_irq_link;
  logic          c_irq_an;
  logic          c_irq_err;
  SGMII_top #(.LT_X(LT_X), .LT_SG(LT_SG)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .gtxd(gtxd),
    .gtx_en(gtx_en),
    .gtx_er(gtx_er),
    .grxd(grxd),
    .grx_dv(grx_dv),
    .grx_er(grx_er),
    .tx_code(tx_code),
    .rx_code(rx_code),
    .mode_sgmii(c_mode_sgmii),
    .an_en(c_an_en),
    .an_restart(c_an_restart),
    .adv(c_adv),
    .sync_ok(c_sync_ok),
    .an_done(c_an_done),
    .link_up(c_link_up),
    .lp_ability(c_lp_ability),
    .speed(c_speed),
    .full_duplex(c_full_duplex),
    .irq_link(c_irq_link),
    .irq_an(c_irq_an),
    .irq_err(c_irq_err)
  );

  // ---------------- registers ----------------
  logic [2:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [17:0] r_CTRL;   // 12'h01C CTRL
  logic [0:0] p_CMD;   // 12'h020 CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 18'h681;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[2:0] & wmask[2:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[2:0]) | (PWDATA[2:0] & wmask[2:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[7]) r_CTRL <= (r_CTRL & ~wmask[17:0]) | (PWDATA[17:0] & wmask[17:0]);
      p_CMD <= (wr && hit[8]) ? PWDATA[0:0] & wmask[0:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_an_en = r_CTRL[0:0];
  assign c_mode_sgmii = r_CTRL[1:1];
  assign c_adv = r_CTRL[17:2];
  assign c_an_restart = p_CMD;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq_link;
    irq_set[1] = c_irq_an;
    irq_set[2] = c_irq_err;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'({c_full_duplex, c_speed, c_link_up, c_an_done, c_sync_ok});
      10'd6: apb_rdata = 32'({c_lp_ability});
      10'd7: apb_rdata = 32'(r_CTRL);
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
